  "system.auto.1ebefvb.101": "عند إغلاق المكوّن المضيف الذي يضم هذا المكوّن، يُبطَل العمل الجاري قبل تحديث DOM التالي له. تتطلب إعادة الفتح تركيبًا جديدًا.",
  "system.auto.1avh66.101": "أعِد استخدام قرار إبداعي أو مخرج سابق للمشروع. يظل كل شيء قابلًا للتعديل في هذا المستند.",
  "system.auto.z7ijvf.70": "أنشئ قرارًا قابلًا لإعادة الاستخدام أو ولّد مخرجًا للمشروع لإعادة استخدامه هنا.",
  "system.auto.1i2qq03.94": "عرض بناءً على طلب صريح فقط؛ يوفّر المكوّن المضيف التحقّق من التبعية للسياق الحالي، ولا يقدّم سجلًا محفوظًا مُختلقًا.",
  "system.auto.tqfa8e.80": "معرّف العملية الأصلية التي لم تُحسم بعد لدى المكوّن المضيف للوصفة فقط؛ دون محتوى الطلب أو إيصال أو إذن بإعادة المحاولة.",
  "system.auto.1w05nuc.88": "يعيد إرسال طلب الحفظ الأصلي لهذه الجلسة صراحةً؛ ولا يُنشئ حالةً جديدة من التعديلات الأحدث، ولا يعيد تطبيقها على أساس جديد.",
  "system.auto.1g1qzzo.110": "ينقل فقط المدخلات التي أعدّها المستخدم إلى واجهة الإدخال القائمة؛ ويلزم مجددًا توفر جميع الصلاحيات المطلوبة للمخرجات قبل تجهيز المقترح.",
  "system.auto.1akiecf.88": "مقترح محلي واحد تابع للسياق الحالي. لا يمكن حفظه بشكل دائم إلا بتنفيذ إجراء «حفظ» صراحةً في البطاقة القائمة.",
  "system.auto.jf2bs7.90": "تقتصر المعالجة على عملية النموذج نفسها التي قبلتها جهة مسؤولة مسجَّلة واحدة؛ ولا يُكتسب أي تحكّم مؤقت في المسار أو التركيز.",
  "system.auto.vcfvld.80": "اسم اختياري قابل للوصول لعنصر التفعيل الأصلي؛ يظل النص المرئي دون تغيير.",
  "system.auto.1eh5z6w.74": "لا يمكن استثناء سوى هذا العارض الحالي بعينه، المخصص للقراءة فقط، من نطاق العنصر الأب.",
  "system.auto.7jaeh8.82": "يقبل فقط مغادرة عادية للواجهة ما زالت صالحة؛ ولا يقيّد أبدًا إجراءات سحب العرض لحماية الخصوصية أو إنهاء التحميل.",
  "system.auto.1qiom3q.70": "مسؤولية دون محتوى تتشاركها الكيانات الحالية المسؤولة عن التنقل في هذه الواجهة.",
  "system.auto.1gfzly6.95": "إغلاق استعادة لم تعد قيد المعالجة ليس إلغاءً؛ تظل المسودات الخام والعمل النشط محدِّدَين لإمكانية المغادرة.",
  "system.auto.wh56ge.77": "تحقّق قبول دون محتوى؛ يظل المستدعي مسؤولًا عن المصدر والمسار والتركيز بآليات المتصفح الأصلية.",
  "system.auto.1uoqax6.83": "تحمي ضوابط المغادرة التعديلات المحلية والعمل قيد التنفيذ، لا البيانات الوصفية وحدها لطلب أصلي لم يعد قيد المعالجة محليًا.",
  "system.auto.1hx4379.98": "للتنقل المقصود في واجهة المستخدم فقط؛ لا تستدعيه العمليات الداخلية للحفظ والاستعادة وسحب الصلاحيات.",
  "system.auto.mkzit3.73": "العمل المحلي الموجود فقط؛ لا يمنح إذنًا ولا يُعدّ إيصالًا أو سلطةً للتنقل.",
  "system.auto.1n5r82s.70": "عرض محلي فقط؛ لا يُعدّ رسالة محادثة أو طلبًا إلى أداة.",
  "system.auto.3wbtph.76": "قراءة الكيانات المسؤولة الحالية؛ يجب ألا يؤكد التنقل استلام عملها أو يتخلّى عنه.",
  "system.auto.d196id.89": "التحقق من قبول المنشأ دون محتوى؛ تبقى هنا الكيانات الأصلية المسؤولة عن الملاحظة والمراجعة والتصحيح.",
  "system.auto.j6sudy.92": "انتظار فتح المسار نفسه تمامًا؛ نجاح التنقل في مخزن الحالة لا يثبت الوصول إلى العارض.",
  "system.auto.1bm0iyt.91": "العمل المحلي فقط. لا تُثبت القيمة \u2068false\u2069 صلاحية المصدر أو القراءة أو المسار حاليًا، ولا تُثبت وجود إذن بالتأليف.",
  "system.auto.1vns05w.99": "إظهار الحالة الموجودة لمُخرَج مؤلَّف حالي واحد فقط؛ دون إنشاء لقطة حالة أو منح صلاحية لإجراء.",
  "system.auto.1ixc2m9.95": "جهة التنفيذ المحلية الموجودة نفسها. يظل التنقل بين الواجهات من مسؤولية مساعد الفتح عديم الحالة.",
  "system.auto.mffe2n.86": "مدخل التحضير الموجود، مع احتفاظ المستدعي بالتحكم طوال عملية الفتح بآليات المتصفح الأصلية.",
  "system.auto.1dlpcpe.28": "لم تُفحص قائمة انتظار هذا الجهاز بعد",
  "system.auto.1ssjjvw.195": "مزامنة Canvas متوقفة مؤقتًا في هذه الصفحة بينما يزيل تخزين الجهاز المحتوى الخاص للمسودات ويحفظ المراجع الأصلية. لم يتم تأكيد استمرار التوقف بعد إعادة تحميل الصفحة بعد. لا تُعِد إرسال التغييرات الأصلية.",
