  "system.auto.jhwcsz.73": "اختر خيارًا واحدًا فقط يحمل تسمية، باستخدام سلوك مفاتيح الأسهم الذي يتحكم فيه المتصفح.",
  "system.auto.17295fh.105": "حدد بدقة ما تتفاعل معه. قد يعيد هذا الدليل ترتيب الخيارات المستقبلية، لكنه لا يستبعدها أبدًا.",
