  "system.auto.1x62wv9.78": "اختر خيارًا واحدًا باستخدام عنصر تحديد أصلي حقيقي وسجلات خيارات JavaScript.",
  "system.auto.1hi8bcc.48": "اختر عدة كتل، ثم ضعها معًا.",
  "system.auto.1212rr9.13": "اختر المصدر",
  "system.auto.15tqkk2.230": "اختر القيمة الإبداعية التي ينبغي أن تثبتها هذه المحاكاة، ثم حدد مسار تطويرها وحجم سجلها ونطاق تغطية المزوّدين. تُحفظ كل محاكاة مكتملة لإعادة تشغيلها وتُربط بحساب منشئ خيالي معزول.",
  "system.auto.5e9al0.88": "اختر المهمة التي يؤديها هذا القرار، ثم حدد ما ينبغي أن يضيفه إلى النتيجة.",
  "system.auto.1a8xjrx.88": "اختر نوع القرار الإبداعي الذي تريد صياغته. يمكنك تعديله أو إزالته لاحقًا.",
  "system.auto.b8re3k.126": "اختر النتيجة التي تساعدك في اتخاذ قرارك التالي. تفتح جميع التنسيقات الإعدادات الكاملة نفسها المتاحة في المستند.",
  "system.auto.1h9xws8.87": "اختر الدور أولًا، ثم صغ القرار بلغة يمكن لأي متعاون العمل بها.",
  "system.auto.7ng3do.21": "اختر حدثًا ظاهرًا…",
  "system.auto.p2hiqs.144": "اختر نوع هذا القرار، ثم حدد ما يجب استبعاده. يظل الدور واضحًا بينما تتحول النية إلى قيد وقائي سلبي.",
  "system.auto.un9mrk.94": "اختر نوع القرار الذي تتحكم فيه هذه الطبقة، ثم امنحه تعليمات دقيقة وحدد مدى تأثيره.",
  "system.auto.1tqagrl.97": "اختر ما تتعلق به التعليمات وكيفية تعامل الخطة معه. يمكنك تغيير كلا الخيارين لاحقًا.",
