  "system.auto.4ty346.144": "صور مرجعية وصور مولّدة محفوظة بشكل دائم. تعمل المجموعات التمثيلية والموسّعة على زيادة التنوع المكاني، بينما يحتفظ خيار الكل بالمجموعة الكاملة المتاحة.",
