  "system.auto.1kw9l2s.24": "مثال: استكشافات العملاء",
  "system.auto.1mtmyvm.26": "مثال: لمسات بلون السيان الكهربائي",
  "system.auto.1ysp9ws.23": "مثال: إضاءة جانبية منخفضة",
  "system.auto.sf4btx.26": "مثال: استكشاف تصاميم التغليف",
  "system.auto.bewxox.39": "مثال: المساحة الهادئة خلف العنصر الرئيسي",
  "system.auto.tkzpxw.156": "يحفظ كل إجراء ترتيبًا قابلاً لإعادة التطبيق لهذا التحديد. ويغيّر طريقة عرض اللوحة فقط، بينما يبقى معنى كل فكرة ومحتواها دون تغيير.",
  "system.auto.b7rujk.90": "لا تعرض كل أداة سوى عناصر التحكم والتقارير التي يحتاجها المستخدمون المصرّح لهم.",
  "system.auto.nywtw1.95": "كل حزمة معتمدة غير قابلة للتعديل ومملوكة للمستأجر، ولا تُطبَّق إلا بعد اختيار مستند.",
  "system.auto.1odr0s.177": "تبدأ كل مجموعة فورًا وتستمر لمدة 30 يومًا. خصّص مقعدًا واحدًا على الأقل لمراجع مستقل. استخدم فقط مواد مصدرية غير حساسة يُصرَّح لفريقك بتقديمها.",
  "system.auto.1ojvk5d.271": "تُعالَج كل صورة باستخدام التنفيذين المحليين. تحافظ الطريقة الحالية على نسبة الأبعاد وتحدد منطقة تركيز متماسكة، بينما يعيد خط الأساس إنتاج مركز البروز للعينة المربعة الأصلية. ولا تُضاف هذه الحسابات إلى أي مستند عن قصد.",
  "system.auto.17k50xd.157": "ترتبط كل استجابة بالقرارات التي أسهمت في تشكيل نتيجتها. وتوضّح هذه الروابط العناصر المؤثرة دون الادعاء بأن خيارًا واحدًا كان سبب كل شيء.",
  "system.auto.1ogqrvi.134": "تهيئ كل قسم جانبًا مختلفًا من النجاح: هدفًا واضحًا، وعالمًا ملموسًا، وتعبيرًا متماسكًا، ونتيجة قابلة للتسليم.",
  "system.auto.1gpduqd.71": "تُراجَع كل صورة مرجعية محددة مرة واحدة فقط، وليس مرة لكل هيكل.",
  "system.auto.1c4rk11.132": "تُحتسَب كل صورة مستقلة أو مجموعة من أربع صور مرة واحدة. ويبقى الاستكشاف البنّاء ظاهرًا بدلاً من تصنيفه خطأً على أنه تخلٍّ عن العمل.",
