  "system.auto.827e70.178": "يلزم توفير أحداث توضّح أن كل دراسة محددة قد تم قفلها واستخدامها في التكوين. اختر تدفقًا أطول أو قلّل عدد الدراسات أو مراحل المزوّد قبل اعتماد العمل المدفوع.",
