  "system.auto.d7at6p.13": "كل مشروع",
  "system.auto.58g7lk.226": "تتحول كل مرحلة من مراحل المزوّد إلى مشروع معزول يضم مستنداته وكتله وعلاقاته ومراجعه ومسوداته وتشعّبات مطالبه ومجموعاته ولوحاته. لا تنسخ هذه العملية بيانات الحساب الحالية ولا تعدّلها مطلقًا.",
  "system.auto.1ya1rc5.95": "تستند كل نتيجة إلى القرارات نفسها وتظل مرتبطة بهذا المستند في جميع طرق العرض.",
  "system.auto.7kwaj6.183": "جميع الصور المحفوظة وعمليات إخراج المستندات الفاشلة لهذا المستند. افحص المطلب غير القابل للتعديل والسياق الثابت وإيصال المرجع والخطأ التقني المرتبط بكل محاولة.",
