  "system.auto.16rfoqn.141": "تظل كل صورة محفوظة مرئية بغض النظر عن الموضع الحالي لإعادة التشغيل. توضّح كل بطاقة وقت ظهورها في عرض التطبيق.",
  "system.auto.1uqr942.59": "تظل جميع العناصر المكانية متاحة دون الحاجة إلى مؤشر.",
