  "system.auto.1frok8u.214": "يبدأ المبدع بهدف غير محدد، وينشئ سياقًا ثابتًا واحدًا، ويستخدم صورًا وقصصًا ومشاهد وعروضًا تقديمية ولوحات قصصية وفيديوهات مصممة لغرض محدد، مع سجل منشأ مشترك وإيصالات تصدير صريحة.",
