  "system.auto.fsgk08.105": "يمكن أن يتحول العمل المنجز إلى سير عمل افتراضي قابل للتراجع، يراعي الحقوق وينشئ شيئًا من العدم.",
  "system.auto.1kyjq4d.193": "تعذّر تسجيل حدث محلي أو الكتابة إلى قاعدة البيانات بينما كان Forma يحفظ هذا المحتوى المُنشأ. لم يتم الإبلاغ عن انقطاع لدى المزود. تواصل مع الدعم أو راجع تشخيصات حفظ البيانات وتخزين الأحداث على الخادم.",
  "system.auto.gz83kn.80": "تتضمن المسودة منخفضة الجودة غاية وافق عليها منشئها وسلسلة نتائج بجودة كاملة.",
  "system.auto.bucbhq.75": "يتم تجميع التحديد المسمّى مع التصريح بأن الترتيب المكاني لا يحمل دلالة معنوية.",
