  "system.auto.1jj1luu.145": "يضمن ملخص استئناف العمل وتشغيل Scout ضمن حدود واضحة والحكم البشري والسياق المقبول الاستمرارية بين الجلسات دون أن تعدّل الوكلاء المستند خفيةً.",
  "system.auto.hhoo0j.160": "يتحول المرجع إلى سياق قابل للتعديل، وتتم ترقية المسودة عمدًا إلى الجودة الكاملة، وتحمل المخرجات الناتجة سجلات النقد والمكتبة والتصدير.",
  "system.auto.zbg2zm.93": "لا يزال طلب هذه النتيجة المحددة مفتوحًا؛ ولا يمكن إكماله باستخدام مستند أو مخرج آخر.",
