  "system.auto.jeuoob.78": "لا يتوافق أي توجه إبداعي موجّه إلى المزوّد مع ميزانية المطالبة المحددة للمحوّل.",
  "system.auto.1ymmpbx.217": "لا توجد إشارة إلى المراجعة أو التقدم أو الاحتفاظ أو الرفض الصريح. تُحتسب تفريعات المطالبة مرة واحدة، بينما تُسجّل عمليات الاستكشاف التي تمت مراجعتها والمسودات التي رُقيت إلى الجودة الكاملة بشكل منفصل بدلًا من تصنيفها خطأً كعناصر مهجورة.",
